const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const easternCanada = ee.Geometry.Rectangle([-85, 45, -55, 60]); // Lon, Lat
  const date1_start = '2023-06-01';
  const date1_end = '2023-06-02';
  const date2_start = '2023-06-05';
  const date2_end = '2023-06-06';

  const collectionId = 'COPERNICUS/S5P/OFFL/L3_CO';
  const coBand = 'CO_column_number_density';
  const qaBand = 'qa_value';

  // 2. Data Acquisition & Processing Function
  const getDailyCo = function(startDate, endDate, geometry) {
    const collection = ee.ImageCollection(collectionId)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .select([coBand, qaBand]);

    if (collection.size().getInfo() === 0) {
      return null; // No images found
    }

    // Create a composite and apply QA mask. QA > 0.5 is recommended for good quality.
    const image = collection.mean();
    const qualityMask = image.select(qaBand).gt(0.5);
    return image.select(coBand).updateMask(qualityMask);
  };

  const image1 = getDailyCo(date1_start, date1_end, easternCanada);
  const image2 = getDailyCo(date2_start, date2_end, easternCanada);

  if (!image1 || !image2) {
