    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const scale = 5000; // Use a coarse scale for large area reduction

  const stats1 = image1.reduceRegion({
    reducer: reducer,
    geometry: easternCanada,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: reducer,
    geometry: easternCanada,
    scale: scale,
    maxPixels: 1e9
  });

  // Execute the computations
  const stats1Info = stats1.getInfo();
  const stats2Info = stats2.getInfo();

  const mean1 = stats1Info['CO_column_number_density_mean'];
  const count1 = stats1Info['CO_column_number_density_count'];
  const mean2 = stats2Info['CO_column_number_density_mean'];
  const count2 = stats2Info['CO_column_number_density_count'];

  // 4. Validation & Final Answer
